import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search product names case-insensitively and return matching products.',
      inputSchema: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'The search query to match against product names (case-insensitive).'
          },
          limit: {
            type: 'integer',
            minimum: 1,
            maximum: 10,
            description: 'Maximum number of results to return (1-10). Defaults to 10.'
          }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = ['query', 'limit'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Invalid argument: "${key}" is not allowed`);
    }
  }

  const { query, limit } = args;

  if (typeof query !== 'string') {
    throw new Error('Invalid argument: "query" must be a string');
  }

  let resolvedLimit = 10;
  if (limit !== undefined) {
    if (!Number.isInteger(limit)) {
      throw new Error('Invalid argument: "limit" must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('Invalid argument: "limit" must be between 1 and 10');
    }
    resolvedLimit = limit;
  }

  const needle = query.toLowerCase();
  const matches = products
    .filter((p) => p.name.toLowerCase().includes(needle))
    .slice(0, resolvedLimit)
    .map((p) => `${p.id}: ${p.name}`);

  const text = matches.length
    ? matches.join('\n')
    : 'No products found';

  return {
    content: [{ type: 'text', text }]
  };
}
